import java.util.*;
public class ColorLinkedListDemo { public static void main(String[] a){LinkedList<String> colors=new LinkedList<>(Arrays.asList("red","blue","yellow","orange"));System.out.println("Forward:");Iterator<String> i=colors.iterator();while(i.hasNext())System.out.println(i.next());System.out.println("Reverse:");ListIterator<String> r=colors.listIterator(colors.size());while(r.hasPrevious())System.out.println(r.previous());LinkedList<String> selected=new LinkedList<>(colors.subList(colors.indexOf("blue"),colors.indexOf("yellow")+1));System.out.println("From blue to yellow: "+selected);} }
